function setCloudStatus(message, tone = '') { const status = document.getElementById('cloudSyncStatus'); if (status) { status.textContent = message; status.className = `cloud-sync-status ${tone}`; } }
function ensureCloudSyncPrompt() { if (document.getElementById('cloudSyncPrompt')) return; document.body.insertAdjacentHTML('beforeend', `<div class="cloud-prompt-backdrop" id="cloudSyncPrompt"><div class="cloud-prompt"><button class="modal-close" id="cloudPromptClose" aria-label="Fechar">×</button><div class="cloud-prompt-symbol">☁<span>✦</span></div><p class="eyebrow">SEU RITMO EM QUALQUER LUGAR</p><h2>Leve o Nimbo com você.</h2><p>Sincronize sua rotina, seus estudos e seus mapas entre o computador e o celular.</p><div class="cloud-prompt-actions"><button class="primary-button" id="cloudPromptStart">Sincronizar agora <span>→</span></button><button class="ghost-button" id="cloudPromptLater">Agora não</button></div><small>Você pode ativar isso depois em Configurações.</small></div></div>`); const close = () => { state.cloudPromptDismissed = true; saveState(); document.getElementById('cloudSyncPrompt').classList.remove('visible'); }; document.getElementById('cloudPromptClose').addEventListener('click', close); document.getElementById('cloudPromptLater').addEventListener('click', close); document.getElementById('cloudPromptStart').addEventListener('click', () => { close(); setView('settings'); document.getElementById('cloudEmail')?.focus(); }); }
function maybeShowCloudPrompt() { if (!cloudReady || cloudUser || state.cloudPromptDismissed || state.nameSetAt !== 'nimbo-name-v1') return; ensureCloudSyncPrompt(); window.setTimeout(() => document.getElementById('cloudSyncPrompt')?.classList.add('visible'), 260); }
function ensureCloudSyncUI() { const grid = document.querySelector('#settingsView .settings-grid'); if (!grid || document.getElementById('cloudSyncPanel')) return; grid.insertAdjacentHTML('beforeend', `<div class="settings-panel cloud-sync-panel" id="cloudSyncPanel"><div class="panel-title"><span>Sincronização</span><small>Seu Nimbo em qualquer dispositivo</small></div><p class="cloud-sync-intro">Entre com a mesma conta no PC e no celular para manter rotina, estudos e mapas sincronizados.</p><div class="cloud-sync-fields"><input id="cloudEmail" type="email" placeholder="Seu e-mail" autocomplete="email" /><div class="cloud-password-field"><input id="cloudPassword" type="password" placeholder="Senha" autocomplete="current-password" /><button type="button" id="cloudPasswordToggle" aria-label="Mostrar senha" title="Mostrar senha"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="2.5"/></svg></button></div></div><small class="cloud-email-note">O e-mail de confirmação chega com remetente Supabase. Confira também a pasta de spam.</small><div class="cloud-sync-actions"><button class="save-button" id="cloudSignIn">Entrar</button><button class="ghost-button" id="cloudSignUp">Criar conta</button><button class="ghost-button" id="cloudResend">Reenviar confirmação</button><button class="ghost-button cloud-signout" id="cloudSignOut">Sair</button></div><small id="cloudSyncStatus" class="cloud-sync-status">Sincronização desligada</small></div>`); document.getElementById('cloudSignIn').addEventListener('click', () => authenticateCloud('signin')); document.getElementById('cloudSignUp').addEventListener('click', () => authenticateCloud('signup')); document.getElementById('cloudResend').addEventListener('click', resendCloudConfirmation); document.getElementById('cloudSignOut').addEventListener('click', async () => { if (cloudClient) await cloudClient.auth.signOut(); }); document.getElementById('cloudPasswordToggle').addEventListener('click', event => { const input = document.getElementById('cloudPassword'); const visible = input.type === 'text'; input.type = visible ? 'password' : 'text'; event.currentTarget.innerHTML = visible ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="2.5"/></svg>' : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 3 18 18M10.6 6.2A10.8 10.8 0 0 1 12 6c6.5 0 10 6 10 6a17.4 17.4 0 0 1-3.3 3.8M6.2 6.3C3.4 8.2 2 12 2 12s3.5 6 10 6c1.8 0 3.3-.4 4.6-1.1"/></svg>'; event.currentTarget.setAttribute('aria-label', visible ? 'Mostrar senha' : 'Ocultar senha'); }); renderCloudSync(); }
function renderCloudSync() { const email = document.getElementById('cloudEmail'); const password = document.getElementById('cloudPassword'); const signIn = document.getElementById('cloudSignIn'); const signUp = document.getElementById('cloudSignUp'); const signOut = document.getElementById('cloudSignOut'); if (!email || !password) return; email.value = cloudUser?.email || ''; email.disabled = Boolean(cloudUser); password.value = ''; password.disabled = Boolean(cloudUser); signIn.disabled = Boolean(cloudUser); signUp.disabled = Boolean(cloudUser); signOut.disabled = !cloudUser; if (cloudUser) setCloudStatus(`Conectado como ${cloudUser.email}.`, 'connected'); else if (cloudReady) setCloudStatus('Entre para sincronizar seus dados.'); }
async function loadSupabase() { if (window.supabase?.createClient) return window.supabase; const module = await import(SUPABASE_SCRIPT_URL); return module; }
async function authenticateCloud(mode) { if (!cloudClient) return setCloudStatus('A conexão ainda está carregando.', 'error'); const email = document.getElementById('cloudEmail')?.value.trim(); const password = document.getElementById('cloudPassword')?.value; if (!email || !password || password.length < 6) return setCloudStatus('Use e-mail e senha com pelo menos 6 caracteres.', 'error'); setCloudStatus(mode === 'signup' ? 'Criando sua conta...' : 'Entrando...'); const redirectUrl = 'https://nimbo-fawn.vercel.app/'; const result = mode === 'signup' ? await cloudClient.auth.signUp({ email, password, options: { emailRedirectTo: redirectUrl } }) : await cloudClient.auth.signInWithPassword({ email, password }); if (result.error) return setCloudStatus(result.error.message, 'error'); if (mode === 'signup' && result.data.user && Array.isArray(result.data.user.identities) && result.data.user.identities.length === 0) return setCloudStatus('Essa conta já existe. Use “Entrar” com sua senha ou “Reenviar confirmação”.', 'error'); if (mode === 'signup' && !result.data.session) return setCloudStatus('Conta criada. O e-mail chega como Supabase. Confira também a pasta de spam.', 'connected'); setCloudStatus('Conta conectada. Sincronizando...'); }
async function resendCloudConfirmation() { if (!cloudClient) return setCloudStatus('A conexão ainda está carregando.', 'error'); const email = document.getElementById('cloudEmail')?.value.trim(); if (!email) return setCloudStatus('Digite seu e-mail para reenviar a confirmação.', 'error'); setCloudStatus('Reenviando confirmação...'); const { error } = await cloudClient.auth.resend({ type: 'signup', email, options: { emailRedirectTo: 'https://nimbo-fawn.vercel.app/' } }); if (error) return setCloudStatus(error.message, 'error'); setCloudStatus('Confirmação reenviada pelo Supabase. Confira entrada, spam e promoções.', 'connected'); }
async function pushCloudState() { if (!cloudClient || !cloudUser || cloudHydrating) return; const payload = { ...state, schemaVersion: 2, updatedAt: Date.now() }; const { error } = await cloudClient.from('nimbo_workspaces').upsert({ user_id: cloudUser.id, state: payload, updated_at: new Date(payload.updatedAt).toISOString() }, { onConflict: 'user_id' }); if (error) setCloudStatus('Não foi possível salvar agora. Seus dados locais continuam seguros.', 'error'); else { state = payload; localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); localStorage.setItem('nimbo-cloud-updated-at', String(payload.updatedAt)); setCloudStatus(`Sincronizado às ${new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}.`, 'connected'); } }
function scheduleCloudSave() { if (!cloudUser || cloudHydrating) return; clearTimeout(cloudSaveTimer); cloudSaveTimer = window.setTimeout(pushCloudState, 700); }
async function handleCloudSession(session) { cloudUser = session?.user || null; renderCloudSync(); if (!cloudUser) return; setCloudStatus('Buscando seus dados...', 'connected'); const { data, error } = await cloudClient.from('nimbo_workspaces').select('state,updated_at').eq('user_id', cloudUser.id).maybeSingle(); if (error) return setCloudStatus('Conta conectada, mas não foi possível buscar os dados.', 'error'); if (data?.state && Object.keys(data.state).length) { const remote = { ...defaultState, ...data.state }; const local = loadState(); const localHasData = Boolean(local.name || local.activities?.length || local.mindMaps?.length > 1 || local.goals?.length || local.studyNotes?.length); const localTime = Number(local.updatedAt || localStorage.getItem('nimbo-cloud-updated-at') || 0); const remoteTime = Number(remote.updatedAt || Date.parse(data.updated_at) || 0); cloudHydrating = true; state = localHasData && localTime > remoteTime ? local : remote; state = { ...defaultState, ...state, schemaVersion: 2, goals: state.goals || [], focusSessions: state.focusSessions || [], studyNotes: state.studyNotes || [] }; localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); cloudHydrating = false; renderAll(); if (state === local) await pushCloudState(); else setCloudStatus('Dados sincronizados com segurança.', 'connected'); } else await pushCloudState(); renderCloudSync(); }
async function initCloudSync() { ensureCloudSyncUI(); try { const supabaseModule = await loadSupabase(); cloudClient = supabaseModule.createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY); cloudReady = true; renderCloudSync(); const { data } = await cloudClient.auth.getSession(); await handleCloudSession(data.session); cloudClient.auth.onAuthStateChange((_event, session) => window.setTimeout(() => handleCloudSession(session), 0)); maybeShowCloudPrompt(); } catch { setCloudStatus('Sincronização indisponível. O modo local continua funcionando.', 'error'); } }

function loadState() { try { const saved = JSON.parse(localStorage.getItem(STORAGE_KEY)); const loaded = saved ? { ...defaultState, ...saved, activities: saved.activities || defaultActivities } : { ...defaultState }; if (!saved?.soundPreferenceSet) loaded.sound = true; if (!loaded.mindMaps?.length) loaded.mindMaps = [{ id: 'main', title: loaded.mindMapTitle || 'Plano 2027', nodes: loaded.mindNodes || defaultState.mindNodes, connections: loaded.mindConnections || [] }]; loaded.activeMindMapId = loaded.activeMindMapId || loaded.mindMaps[0].id; const active = loaded.mindMaps.find(map => map.id === loaded.activeMindMapId) || loaded.mindMaps[0]; loaded.activeMindMapId = active.id; loaded.mindMapTitle = active.title; loaded.mindNodes = active.nodes; loaded.mindConnections = active.connections; return loaded; } catch { return { ...defaultState, mindMaps: [{ id: 'main', title: 'Plano 2027', nodes: defaultState.mindNodes, connections: [] }] }; } }
function syncActiveMindMap() { const active = state.mindMaps?.find(map => map.id === state.activeMindMapId); if (active) { active.title = state.mindMapTitle; active.nodes = state.mindNodes; active.connections = state.mindConnections; } }
function saveState() { syncActiveMindMap(); state.schemaVersion = 2; state.updatedAt = Date.now(); localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); scheduleCloudSave(); }
function loadActiveMindMap() { const active = state.mindMaps.find(map => map.id === state.activeMindMapId); if (!active) return; state.mindMapTitle = active.title; state.mindNodes = active.nodes; state.mindConnections = active.connections; }
function esc(value) { return String(value).replace(/[&<>'"]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[c])); }
function safeUrl(value) { try { const url = new URL(value); return ['http:', 'https:'].includes(url.protocol) ? url.href : ''; } catch { return ''; } }
function initials(name) { return (name || 'Usuário').trim().slice(0, 1).toUpperCase(); }
function currentDay() { return new Date().getDay(); }
function todaysActivities() { const day = currentDay(); const today = dateKey(); return state.activities.filter(a => a.postponedFor === today || (a.days.includes(day) && a.postponedFor !== today)).sort((a,b) => a.time.localeCompare(b.time)); }
function formatDuration(minutes) { if (minutes >= 60) return `${Math.floor(minutes/60)}h${minutes%60 ? ` ${String(minutes%60).padStart(2,'0')}` : ''}`; return `${minutes} min`; }
function categoryLabel(category) { return ({ focus: 'FOCO', chess: 'XADREZ', body: 'CORPO', life: 'VIDA', rest: 'PAUSA' })[category] || 'ATIVIDADE'; }
function categoryIcon(category) { return ({ focus: '◒', chess: '♟', body: '✦', life: '⌁', rest: '☾' })[category] || '◒'; }
function setText(id, value) { const el = document.getElementById(id); if (el) el.textContent = value; }
function dayGreeting() { const hour = new Date().getHours(); return hour >= 18 ? 'Boa noite' : hour >= 12 ? 'Boa tarde' : 'Bom dia'; }
function musicIcon(enabled) { return enabled ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18V5l11-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="17" cy="16" r="3"/><path d="M21 8c1.2 1 1.2 3 0 4M23 6c2.1 2 2.1 6 0 8"/></svg>' : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18V5l11-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="17" cy="16" r="3"/><path d="m3 3 18 18"/></svg>'; }

function renderHeader() {
  const displayName = state.name || 'Usuário';
  ['greetingName','sideName'].forEach(id => setText(id, displayName));
  ['avatarLetter','topAvatar'].forEach(id => setText(id, initials(state.name)));
  const date = new Date();
  setText('dayNumber', String(date.getDate()).padStart(2,'0'));
  setText('dateLabel', date.toLocaleDateString('pt-BR', { day:'2-digit', month:'short', year:'numeric' }).replace('.', '').toUpperCase());
  setText('intentionText', state.intention || defaultState.intention);
  setText('focusLabel', state.focusLabel || defaultState.focusLabel); const focusInput = document.getElementById('focusLabelInput'); if (focusInput) focusInput.value = state.focusLabel || defaultState.focusLabel;
  setText('skyGreeting', `${dayGreeting()}, ${displayName}`);
  applyTheme();
  document.querySelectorAll('.theme-option').forEach(option => option.classList.toggle('active', option.dataset.theme === state.theme));
  document.getElementById('soundSwitch').classList.toggle('on', state.sound);
  document.getElementById('soundIcon').innerHTML = musicIcon(state.sound); document.getElementById('soundToggle').classList.toggle('is-playing', state.sound); document.getElementById('soundToggle').setAttribute('aria-label', state.sound ? 'Pausar música ambiente' : 'Ativar música ambiente');
  document.getElementById('volumeRange').value = state.volume;
}

function applyTheme() { const systemLight = window.matchMedia?.('(prefers-color-scheme: light)').matches; const light = state.theme === 'light' || (state.theme === 'auto' && systemLight); document.body.classList.toggle('light', light); document.documentElement.dataset.theme = light ? 'light' : 'dark'; document.querySelectorAll('.theme-option').forEach(option => option.classList.toggle('active', option.dataset.theme === (state.theme || 'auto'))); }

function renderToday() {
  const activities = todaysActivities();
  const completed = activities.filter(a => a.done).length;
  const percent = activities.length ? Math.round(completed / activities.length * 100) : 0;
  setText('progressPercent', `${percent}%`); setText('sideProgress', `${percent}%`);
  document.getElementById('mainProgressBar').style.width = `${percent}%`; document.getElementById('sideProgressBar').style.width = `${percent}%`;
  setText('focusTime', formatDuration(activities.filter(a => a.done).reduce((sum,a) => sum+a.duration, 0)));
  const dots = document.getElementById('focusDots'); dots.innerHTML = Array.from({ length: 7 }, (_, i) => `<i class="${i < Math.ceil(percent / 15) ? '' : 'empty'}"></i>`).join('');
  setText('chessCount', `${activities.filter(a => a.done && a.category === 'chess').length} partidas`);
  setText('studyCount', `${activities.filter(a => a.done && a.category === 'focus').reduce((sum,a) => sum+a.duration,0)} min`);
  document.getElementById('timeline').innerHTML = activities.map(activity => `<div class="timeline-item ${activity.done ? 'done' : ''}"><div class="timeline-time">${esc(activity.time)}</div><span class="timeline-dot"></span><div class="task-card" data-open-id="${esc(activity.id)}"><input class="task-check" type="checkbox" data-task-id="${esc(activity.id)}" ${activity.done ? 'checked' : ''} aria-label="Concluir ${esc(activity.name)}"><div class="task-info"><strong>${esc(activity.name)}</strong><small>${esc(activity.description || 'Atividade personalizada')}</small></div><span class="task-tag ${esc(activity.category)}">${categoryLabel(activity.category)}</span><span class="task-duration">${formatDuration(activity.duration)}</span>${activity.link ? '<span class="attachment-indicator">↗</span>' : ''}${activity.image ? '<span class="attachment-indicator">▧</span>' : ''}<button class="edit-task" data-edit-id="${esc(activity.id)}" aria-label="Editar atividade">✎</button></div></div>`).join('') || '<div class="empty-state">Nenhuma atividade neste dia. Adicione algo leve para começar.</div>';
  document.querySelectorAll('.task-check').forEach(check => check.addEventListener('change', () => toggleTask(check.dataset.taskId)));
  document.querySelectorAll('.edit-task').forEach(button => button.addEventListener('click', () => openActivityModal(button.dataset.editId)));
  document.querySelectorAll('.task-card').forEach(card => card.addEventListener('click', event => { if (event.target.closest('input,button')) return; card.classList.add('editor-highlight'); setTimeout(() => openActivityModal(card.dataset.openId), 260); }));
}

function dateKey(date = new Date()) { return date.toISOString().slice(0, 10); }
function activityStatus(activity) { if (activity.done) return 'Concluída'; if (activity.ignoredOn === dateKey()) return 'Ignorada'; if (activity.postponedFor === dateKey()) return 'Adiada'; const [hours, minutes] = activity.time.split(':').map(Number); const current = new Date(); const start = hours * 60 + minutes; const now = current.getHours() * 60 + current.getMinutes(); if (now >= start && now < start + Number(activity.duration || 0)) return 'Em andamento'; return now < start ? 'Próxima' : 'Pendente'; }
function postponeActivity(id) { const activity = state.activities.find(item => item.id === id); if (!activity) return; const tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate() + 1); activity.postponedFor = dateKey(tomorrow); activity.done = false; saveState(); renderAll(); showToast('Atividade adiada para amanhã.'); }
function ignoreActivity(id) { const activity = state.activities.find(item => item.id === id); if (!activity) return; activity.ignoredOn = activity.ignoredOn === dateKey() ? '' : dateKey(); activity.done = false; saveState(); renderAll(); showToast(activity.ignoredOn ? 'Atividade marcada como ignorada hoje.' : 'Atividade voltou para o dia.'); }
