function renderMindConnections() { const map = document.getElementById('mindMap'); const svg = document.getElementById('mindConnections'); const center = map?.querySelector('.mind-center'); if (!map || !svg || !center) return; applyMindDimensions(); const mapRect = map.getBoundingClientRect(); const centerRect = center.getBoundingClientRect(); const cx = centerRect.left - mapRect.left + centerRect.width / 2; const cy = centerRect.top - mapRect.top + centerRect.height / 2; const getPoint = node => { const rect = node.getBoundingClientRect(); return { x: rect.left - mapRect.left + rect.width / 2, y: rect.top - mapRect.top + rect.height / 2 }; }; const makeCurve = (from, to, manual = false) => { const bend = manual ? (to.x - from.x) * .2 + (to.y - from.y) * .08 : (to.x - from.x) * .16; return `<path class="${manual ? 'manual-connection' : ''}" d="M ${from.x} ${from.y} Q ${(from.x + to.x) / 2} ${from.y - bend} ${to.x} ${to.y}" />`; }; const autoLines = [...map.querySelectorAll('.mind-node')].map(node => { const point = getPoint(node); return state.mindSettings?.lineStyle === 'soft' ? makeCurve({ x: cx, y: cy }, point) : `<line x1="${cx}" y1="${cy}" x2="${point.x}" y2="${point.y}" />`; }); const nodesById = new Map([...map.querySelectorAll('.mind-node')].map(node => [node.querySelector('[data-delete-node]')?.dataset.deleteNode, node])); const manualLines = (state.mindConnections || []).map(([fromId, toId]) => { const from = nodesById.get(fromId); const to = nodesById.get(toId); return from && to ? makeCurve(getPoint(from), getPoint(to), true) : ''; }); svg.setAttribute('viewBox', `0 0 ${mapRect.width} ${mapRect.height}`); svg.innerHTML = autoLines.concat(manualLines).join(''); }
