function renderAtmosphere() { setText('atmosphereStatus', state.sound ? 'reproduzindo' : 'pausado'); setText('atmosphereTitle', state.sound ? ({ rain: 'Chuva macia', forest: 'Floresta calma', waves: 'Ondas lentas', fire: 'Lareira acesa', night: 'Noite tranquila' }[state.ambience] || 'Paisagem sonora') : 'Silêncio pronto'); setText('atmosphereDescription', state.sound ? 'O som foi iniciado por você e pode ser pausado a qualquer momento.' : 'Escolha uma paisagem e aperte play quando quiser começar.'); setText('atmosphereIcon', state.sound ? '♫' : '☾'); const ambience = document.getElementById('ambienceVolume'); const music = document.getElementById('musicVolume'); if (ambience) ambience.value = state.ambienceVolume ?? 55; if (music) music.value = state.musicVolume ?? 45; document.querySelectorAll('[data-ambience]').forEach(button => button.classList.toggle('active', button.dataset.ambience === state.ambience)); document.querySelectorAll('[data-music]').forEach(button => button.classList.toggle('active', button.dataset.music === state.music)); }
