function toggleTask(id) { const activity = state.activities.find(a => a.id === id); if (!activity) return; activity.done = !activity.done; if (activity.done) { activity.ignoredOn = ''; activity.postponedFor = ''; } saveState(); renderToday(); renderWeek(); showToast(activity.done ? 'Feito. Um passo de cada vez.' : 'Atividade reaberta.'); }
