function showToast(message) { const toast = document.getElementById('toast'); toast.textContent = message; toast.classList.add('show'); setTimeout(() => toast.classList.remove('show'), 2400); }

function openActivityModal(id = null) { editingId = id; pendingImage = ''; const activity = state.activities.find(a => a.id === id); document.getElementById('activityModal').classList.add('visible'); document.getElementById('activityModalEyebrow').textContent = id ? 'EDITAR ATIVIDADE' : 'NOVA ATIVIDADE'; document.getElementById('activityModalTitle').textContent = id ? 'Ajustar ao seu ritmo' : 'Adicionar ao seu ritmo'; document.getElementById('activityName').value = activity?.name || ''; document.getElementById('activityDescription').value = activity?.description || ''; document.getElementById('activityTime').value = activity?.time || '16:00'; document.getElementById('activityDuration').value = activity?.duration || 30; document.getElementById('activityCategory').value = activity?.category || 'focus'; document.getElementById('activityLink').value = activity?.link || ''; const preview = document.getElementById('imagePreview'); preview.textContent = activity?.image ? 'Imagem anexada' : '＋ Anexar imagem'; preview.style.backgroundImage = activity?.image ? `url(${activity.image})` : ''; preview.classList.toggle('has-image', Boolean(activity?.image)); document.getElementById('deleteActivityBtn').style.display = id ? 'block' : 'none'; document.getElementById('dayPicker').innerHTML = dayNames.map((day, index) => `<button type="button" class="day-choice ${(activity?.days || [0,1,2,3,4,5,6]).includes(index) ? 'selected' : ''}" data-day="${index}">${day.slice(0,1)}</button>`).join(''); document.querySelectorAll('.day-choice').forEach(button => button.addEventListener('click', () => button.classList.toggle('selected'))); }
