function saveActivity(event) { event.preventDefault(); const days = [...document.querySelectorAll('.day-choice.selected')].map(button => Number(button.dataset.day)); if (!days.length) return showToast('Escolha pelo menos um dia.'); const wasEditing = Boolean(editingId); const previous = state.activities.find(a => a.id === editingId); const activity = { id: editingId || `activity-${Date.now()}`, name: document.getElementById('activityName').value.trim(), time: document.getElementById('activityTime').value, duration: Number(document.getElementById('activityDuration').value), category: document.getElementById('activityCategory').value, days, description: document.getElementById('activityDescription').value.trim() || 'Atividade personalizada', link: document.getElementById('activityLink').value.trim(), image: pendingImage || previous?.image || '', done: previous?.done || false }; if (editingId) state.activities = state.activities.map(a => a.id === editingId ? activity : a); else state.activities.push(activity); saveState(); closeActivityModal(); renderAll(); showToast(wasEditing ? 'Atividade atualizada.' : 'Nova atividade adicionada.'); }

function setView(view) { document.querySelectorAll('.view').forEach(section => section.classList.remove('active-view')); const target = document.getElementById(`${view}View`); if (!target) return; target.classList.add('active-view'); document.querySelectorAll('.nav-item[data-view]').forEach(button => button.classList.toggle('active', button.dataset.view === view)); setText('pageCrumb', ({ today:'Início', week:'Minha rotina', library:'Atividades', goals:'Objetivos', studies:'Estudos', atmosphere:'Atmosfera', studio:'Estúdio', settings:'Configurações' })[view] || view); document.getElementById('sidebar').classList.remove('open'); }
function playAmbientNote(frequency, duration = 2.8) { if (!audioContext || !masterGain) return; const oscillator = audioContext.createOscillator(); const gain = audioContext.createGain(); const now = audioContext.currentTime; oscillator.type = 'sine'; oscillator.frequency.setValueAtTime(frequency, now); oscillator.detune.value = -4; gain.gain.setValueAtTime(0.0001, now); gain.gain.exponentialRampToValueAtTime(0.12, now + .12); gain.gain.exponentialRampToValueAtTime(0.0001, now + duration); oscillator.connect(gain).connect(masterGain); oscillator.start(now); oscillator.stop(now + duration + .1); }
function setupAudio() { try { if (!audioContext) { const AudioEngine = window.AudioContext || window.webkitAudioContext; if (!AudioEngine) throw new Error('Audio não suportado'); audioContext = new AudioEngine(); masterGain = audioContext.createGain(); masterGain.gain.value = Math.max(.16, state.volume / 100 * 1.9); compressorNode = audioContext.createDynamicsCompressor(); compressorNode.threshold.value = -20; compressorNode.knee.value = 16; compressorNode.ratio.value = 5; compressorNode.attack.value = .01; compressorNode.release.value = .25; masterGain.connect(compressorNode).connect(audioContext.destination); const frequencies = [130.81, 164.81, 196]; frequencies.forEach((frequency, index) => { const oscillator = audioContext.createOscillator(); const gain = audioContext.createGain(); oscillator.type = index === 1 ? 'sine' : 'triangle'; oscillator.frequency.value = frequency; gain.gain.value = .06 / (index + 1); oscillator.connect(gain).connect(masterGain); oscillator.start(); ambientNodes.push(oscillator, gain); }); const patterns = [[261.63, 329.63, 392, 329.63, 293.66, 349.23, 440, 349.23], [261.63, 329.63, 392, 523.25, 440, 523.25, 659.25, 523.25], [392, 349.23, 329.63, 261.63, 293.66, 329.63, 392, 440]]; ambientStep = 0; ambientPattern = 0; playAmbientNote(patterns[0][0], .62); ambientTimer = window.setInterval(() => { if (ambientStep > 0 && ambientStep % 8 === 0) ambientPattern = Math.floor(ambientStep / 8) % 3 === 2 ? 1 : 0; const melody = patterns[ambientPattern]; playAmbientNote(melody[ambientStep % melody.length], .62); if (ambientStep % 4 === 0) playAmbientNote(melody[(ambientStep + 2) % melody.length] / 2, 1.05); if (ambientPattern === 1 && ambientStep % 2 === 0) playAmbientNote(melody[(ambientStep + 3) % melody.length] * 2, .34); ambientStep += 1; }, 720); } else if (masterGain) { masterGain.gain.setTargetAtTime(Math.max(.16, state.volume / 100 * 1.9), audioContext.currentTime, .03); } if (audioContext.state === 'suspended') audioContext.resume(); } catch { stopAudio(); state.sound = false; saveState(); renderHeader(); showToast('O navegador bloqueou o áudio. Clique novamente para tentar.'); } }
function stopAudio() { if (ambientTimer) { clearInterval(ambientTimer); ambientTimer = null; } if (!audioContext) return; ambientNodes.forEach(node => { try { node.disconnect(); } catch {} }); ambientNodes = []; masterGain = null; compressorNode = null; audioContext.close(); audioContext = null; }
function updateSound(enabled) { state.sound = enabled; state.soundPreferenceSet = true; saveState(); if (enabled) setupAudio(); else stopAudio(); renderHeader(); if (state.sound) showToast('Som ambiente ligado.'); else if (!enabled) showToast('Som ambiente pausado.'); }
function autoStartAudio() { return; }
function playAmbientNote(frequency, duration = 2.8, bus = 'music') { if (!audioContext || !masterGain) return; const destination = bus === 'ambient' ? (ambientGain || masterGain) : (musicGain || masterGain); const oscillator = audioContext.createOscillator(); const gain = audioContext.createGain(); const now = audioContext.currentTime; oscillator.type = bus === 'ambient' ? 'sine' : 'triangle'; oscillator.frequency.setValueAtTime(frequency, now); oscillator.detune.value = -4; gain.gain.setValueAtTime(0.0001, now); gain.gain.exponentialRampToValueAtTime(bus === 'ambient' ? .08 : .12, now + .12); gain.gain.exponentialRampToValueAtTime(0.0001, now + duration); oscillator.connect(gain).connect(destination); oscillator.start(now); oscillator.stop(now + duration + .1); }
function setupAudio() { try { if (!audioContext) { const AudioEngine = window.AudioContext || window.webkitAudioContext; if (!AudioEngine) throw new Error('Audio não suportado'); audioContext = new AudioEngine(); masterGain = audioContext.createGain(); ambientGain = audioContext.createGain(); musicGain = audioContext.createGain(); compressorNode = audioContext.createDynamicsCompressor(); masterGain.gain.value = Math.max(.12, (state.volume ?? 60) / 100 * 1.7); ambientGain.gain.value = Math.max(.02, (state.ambienceVolume ?? 55) / 100); musicGain.gain.value = Math.max(.02, (state.musicVolume ?? 45) / 100); ambientGain.connect(masterGain); musicGain.connect(masterGain); masterGain.connect(compressorNode).connect(audioContext.destination); const base = ({ rain: 130.81, forest: 98, waves: 73.42, fire: 146.83, night: 65.41 }[state.ambience] || 130.81); [base, base * 1.25, base * 1.5].forEach((frequency, index) => { const oscillator = audioContext.createOscillator(); const gain = audioContext.createGain(); oscillator.type = index === 1 ? 'sine' : 'triangle'; oscillator.frequency.value = frequency; gain.gain.value = .035 / (index + 1); oscillator.connect(gain).connect(ambientGain); oscillator.start(); ambientNodes.push(oscillator, gain); }); const patterns = { calm: [261.63, 329.63, 392, 329.63, 293.66, 349.23, 440, 349.23], focus: [220, 261.63, 329.63, 392, 329.63, 261.63, 293.66, 349.23], bright: [293.66, 349.23, 440, 523.25, 440, 392, 493.88, 587.33] }; const melody = patterns[state.music] || patterns.calm; ambientStep = 0; ambientPattern = 0; playAmbientNote(melody[0], .62, 'music'); ambientTimer = window.setInterval(() => { if (ambientStep > 0 && ambientStep % 8 === 0) ambientPattern = Math.floor(ambientStep / 8) % 3 === 2 ? 1 : 0; const current = ambientPattern === 1 && state.music === 'bright' ? patterns.bright : melody; playAmbientNote(current[ambientStep % current.length], .62, 'music'); if (ambientStep % 4 === 0) playAmbientNote(current[(ambientStep + 2) % current.length] / 2, 1.05, 'music'); if (state.music === 'bright' && ambientStep % 2 === 0) playAmbientNote(current[(ambientStep + 3) % current.length] * 2, .34, 'music'); ambientStep += 1; }, 720); } else if (masterGain) { masterGain.gain.setTargetAtTime(Math.max(.12, (state.volume ?? 60) / 100 * 1.7), audioContext.currentTime, .03); ambientGain?.gain.setTargetAtTime(Math.max(.02, (state.ambienceVolume ?? 55) / 100), audioContext.currentTime, .03); musicGain?.gain.setTargetAtTime(Math.max(.02, (state.musicVolume ?? 45) / 100), audioContext.currentTime, .03); } if (audioContext.state === 'suspended') audioContext.resume(); } catch { stopAudio(); state.sound = false; saveState(); renderHeader(); showToast('O navegador bloqueou o áudio. Clique novamente para tentar.'); } }
function stopAudio() { if (ambientTimer) { clearInterval(ambientTimer); ambientTimer = null; } if (!audioContext) return; ambientNodes.forEach(node => { try { node.disconnect(); } catch {} }); ambientNodes = []; ambientGain = null; musicGain = null; masterGain = null; compressorNode = null; audioContext.close(); audioContext = null; }
function updateSound(enabled) { state.sound = enabled; state.soundPreferenceSet = true; saveState(); if (enabled) setupAudio(); else stopAudio(); renderHeader(); renderAtmosphere(); if (state.sound) showToast('Atmosfera ligada.'); else showToast('Atmosfera pausada.'); }

function updateOpeningSky(code = null) { const opening = document.getElementById('appOpening'); if (!opening) return; opening.classList.remove('weather-night', 'weather-cloudy', 'weather-overcast'); const hour = new Date().getHours(); if (hour < 6 || hour >= 18) opening.classList.add('weather-night'); else if (code !== null && code >= 80) opening.classList.add('weather-overcast'); else if (code !== null && code >= 1) opening.classList.add('weather-cloudy'); }
function normalizeBranding() { document.title = 'Nimbo · rotina com presença'; const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode); nodes.forEach(node => { if (node.nodeValue.includes('NIMBO')) node.nodeValue = node.nodeValue.replaceAll('NIMBO', 'Nimbo'); }); }
function weatherCondition(code, hour = new Date().getHours(), short = false) { const night = hour < 6 || hour >= 18; if (code === null) return night ? 'céu noturno' : 'clima local'; if (code === 0) return night ? 'céu limpo' : 'ensolarado'; if (code === 1 || code === 2) return 'parcialmente nublado'; if (code === 3) return 'nublado'; if (code === 45 || code === 48) return 'neblina'; if (code >= 51 && code <= 57) return 'garoa'; if (code >= 61 && code <= 67) return 'chovendo'; if (code >= 71 && code <= 77) return 'neve'; if (code >= 80 && code <= 82) return 'pancadas de chuva'; if (code >= 85 && code <= 86) return 'pancadas de neve'; if (code >= 95) return 'tempestade'; return short ? 'clima variável' : 'clima local'; }
function weatherLabel(code, hour = new Date().getHours()) { return weatherCondition(code, hour, true); }
function updateSky(code = null, temperature = null) { const hour = new Date().getHours(); document.body.classList.remove('weather-night', 'weather-cloudy', 'weather-overcast'); updateOpeningSky(code); const label = weatherLabel(code, hour); const condition = weatherCondition(code, hour); const degrees = temperature === null ? '—°C' : `${Math.round(temperature)}°C`; setText('weatherTemp', degrees); setText('openingWeather', `${degrees} · ${label}`); const isNight = hour < 6 || hour >= 18; setText('weatherStatus', isNight ? `NOITE · ${condition.toUpperCase()}` : condition.toUpperCase()); if (isNight) { document.body.classList.add('weather-night'); setText('weatherMessage', 'A noite também pode ser um lugar tranquilo para recomeçar.'); return; } if (code !== null && code >= 80) { document.body.classList.add('weather-overcast'); setText('weatherMessage', 'Nublado por aí. Um ritmo mais macio combina com hoje.'); return; } if (code !== null && code >= 1) { document.body.classList.add('weather-cloudy'); setText('weatherMessage', 'Nuvens passam. Seu próximo passo continua aqui.'); return; } setText('weatherMessage', 'Um plano leve para um dia com intenção.'); }
async function loadWeather() { updateSky(); if (!navigator.geolocation) return; navigator.geolocation.getCurrentPosition(async position => { try { const { latitude, longitude } = position.coords; const response = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${latitude}&longitude=${longitude}&current=weather_code,temperature_2m&timezone=auto`); const weather = await response.json(); updateSky(weather.current?.weather_code ?? null, weather.current?.temperature_2m ?? null); } catch { updateSky(); } }, () => updateSky(), { maximumAge: 1800000, timeout: 5000 }); }
function startOpening() { const opening = document.getElementById('appOpening'); const name = state.name?.trim(); const confirmedName = name && state.nameSetAt === 'nimbo-name-v1'; const hour = new Date().getHours(); updateOpeningSky(); document.getElementById('openingGreeting').textContent = confirmedName ? `${dayGreeting()}, ${name}` : dayGreeting(); document.getElementById('openingMessage').textContent = hour >= 18 ? 'desacelerando o mundo para você' : hour >= 12 ? 'organizando um dia que ainda está acontecendo' : 'preparando um dia bonito para você'; window.setTimeout(() => { opening.classList.add('ready'); maybeShowCloudPrompt(); }, 2200); }

