  normalizeBranding(); const needsName = state.nameSetAt !== 'nimbo-name-v1'; const opening = document.getElementById('appOpening'); if (needsName) { opening.classList.add('awaiting-name'); document.getElementById('welcomeModal').classList.add('visible'); } else startOpening(); renderAll(); loadWeather(); if (state.sound) { autoStartAudio(); window.addEventListener('pointerdown', () => { if (audioContext?.state === 'suspended') audioContext.resume(); }, { once: true }); }
