function ensureSettingsEnhancements() { const view = document.getElementById('settingsView'); if (!view || document.getElementById('dataToolsPanel')) return; view.insertAdjacentHTML('beforeend', `<div class="settings-extra-grid"><div class="settings-panel" id="dataToolsPanel"><div class="panel-title"><span>Seus dados</span><small>Leve seu espaço com você</small></div><p class="settings-help">Exporte uma cópia ou importe um arquivo salvo anteriormente. O Nimbo continua funcionando sem conta.</p><div class="data-actions"><button class="ghost-button" id="exportDataBtn">Exportar JSON</button><button class="ghost-button" id="importDataBtn">Importar JSON</button><input id="importDataInput" type="file" accept="application/json" hidden /><button class="danger-button" id="resetDataBtn">Restaurar dados</button></div></div><div class="settings-panel faq-panel"><div class="panel-title"><span>Perguntas frequentes</span><small>Respostas curtas para usar melhor o Nimbo</small></div><div class="faq-list"><button class="faq-item" type="button"><span>Como personalizo minha rotina?</span><b>＋</b><p>Abra Minha rotina ou Atividades e use Nova atividade. Você pode escolher horário, duração, dias, categoria, descrição, imagem e link.</p></button><button class="faq-item" type="button"><span>Como funciona o progresso?</span><b>＋</b><p>Ele é calculado somente a partir das atividades marcadas como concluídas no dia.</p></button><button class="faq-item" type="button"><span>O áudio começa sozinho?</span><b>＋</b><p>Não. A reprodução só começa depois que você aperta play em Atmosfera ou no botão de som.</p></button><button class="faq-item" type="button"><span>Onde ficam meus dados?</span><b>＋</b><p>Sem login, ficam no navegador. Com login, a rotina é sincronizada na sua conta do Supabase.</p></button></div></div></div>`); document.getElementById('exportDataBtn').addEventListener('click', () => { const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `nimbo-backup-${dateKey()}.json`; link.click(); URL.revokeObjectURL(url); showToast('Backup exportado.'); }); document.getElementById('importDataBtn').addEventListener('click', () => document.getElementById('importDataInput').click()); document.getElementById('importDataInput').addEventListener('change', event => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const imported = JSON.parse(reader.result); if (!imported || !Array.isArray(imported.activities)) throw new Error('Formato inválido'); state = { ...defaultState, ...imported, schemaVersion: 2, updatedAt: Date.now(), goals: imported.goals || [], focusSessions: imported.focusSessions || [], studyNotes: imported.studyNotes || [] }; saveState(); renderAll(); showToast('Backup importado.'); } catch { showToast('Não foi possível importar esse arquivo.'); } event.target.value = ''; }; reader.readAsText(file); }); document.getElementById('resetDataBtn').addEventListener('click', () => { if (!window.confirm('Restaurar o Nimbo e apagar suas personalizações locais?')) return; localStorage.removeItem(STORAGE_KEY); location.reload(); }); document.querySelectorAll('.faq-item').forEach(item => item.addEventListener('click', () => { item.classList.toggle('open'); item.querySelector('b').textContent = item.classList.contains('open') ? '×' : '＋'; })); }
