document.addEventListener('DOMContentLoaded', () => { ensureSettingsEnhancements(); const duration = document.getElementById('studyHomeDuration'); const setDuration = value => { let minutes = value === 'custom' ? Number(window.prompt('Quantos minutos você quer estudar?', '30')) : Number(value); if (!Number.isFinite(minutes) || minutes < 1) { if (duration) duration.value = '25'; minutes = 25; } studyHomeSeconds = Math.round(minutes * 60); setText('studyHomeTimer', `${String(Math.floor(studyHomeSeconds / 60)).padStart(2, '0')}:00`); }; duration?.addEventListener('change', event => setDuration(event.target.value)); document.getElementById('studyHomeReset')?.addEventListener('click', () => { const minutes = duration?.value === 'custom' ? 30 : Number(duration?.value || 25); studyHomeSeconds = minutes * 60; setText('studyHomeTimer', `${String(minutes).padStart(2, '0')}:00`); }); });
