let stableMindDragBound = false;
function enableStableMindDragging() { const map = document.getElementById('mindMap'); if (!map || stableMindDragBound) return; stableMindDragBound = true; map.addEventListener('pointerdown', event => { if (map.classList.contains('drawing-lines')) return; const node = event.target.closest('.mind-node'); if (!node || event.target.closest('button,a')) return; event.preventDefault(); event.stopImmediatePropagation(); const mapRect = map.getBoundingClientRect(); const nodeRect = node.getBoundingClientRect(); const offsetX = event.clientX - nodeRect.left; const offsetY = event.clientY - nodeRect.top; node.classList.add('dragging'); const move = moveEvent => { moveEvent.preventDefault(); const left = Math.max(1, Math.min(86, ((moveEvent.clientX - mapRect.left - offsetX) / mapRect.width) * 100)); const top = Math.max(2, Math.min(86, ((moveEvent.clientY - mapRect.top - offsetY) / mapRect.height) * 100)); node.style.left = `${left}%`; node.style.top = `${top}%`; node.dataset.dragX = left; node.dataset.dragY = top; renderMindConnections(); }; const end = () => { const item = state.mindNodes.find(nodeItem => nodeItem.id === node.querySelector('[data-delete-node]')?.dataset.deleteNode); if (item && node.dataset.dragX) { item.x = Number(node.dataset.dragX); item.y = Number(node.dataset.dragY); saveState(); } node.classList.remove('dragging'); document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', end); document.removeEventListener('pointercancel', end); renderMindConnections(); }; document.addEventListener('pointermove', move, { passive: false }); document.addEventListener('pointerup', end, { once: true }); document.addEventListener('pointercancel', end, { once: true }); }, true); }
document.addEventListener('DOMContentLoaded', enableStableMindDragging);
let documentMindDragBound = false;
function enableDocumentMindDragging() { if (documentMindDragBound) return; documentMindDragBound = true; document.addEventListener('pointerdown', event => { const map = document.getElementById('mindMap'); if (!map || map.classList.contains('drawing-lines')) return; const node = event.target.closest('.mind-node'); if (!node || !map.contains(node) || event.target.closest('button,a')) return; event.preventDefault(); event.stopImmediatePropagation(); const mapRect = map.getBoundingClientRect(); const nodeRect = node.getBoundingClientRect(); const resizing = map.classList.contains('resize-mode'); const offsetX = event.clientX - nodeRect.left; const offsetY = event.clientY - nodeRect.top; const startWidth = nodeRect.width; const startHeight = nodeRect.height; node.classList.add('dragging'); const move = moveEvent => { moveEvent.preventDefault(); if (resizing) { const width = Math.max(110, Math.min(340, startWidth + moveEvent.clientX - event.clientX)); const height = Math.max(55, Math.min(260, startHeight + moveEvent.clientY - event.clientY)); node.style.width = `${width}px`; node.style.height = `${height}px`; node.dataset.dragWidth = width; node.dataset.dragHeight = height; } else { const left = Math.max(1, Math.min(86, ((moveEvent.clientX - mapRect.left - offsetX) / mapRect.width) * 100)); const top = Math.max(2, Math.min(86, ((moveEvent.clientY - mapRect.top - offsetY) / mapRect.height) * 100)); node.style.left = `${left}%`; node.style.top = `${top}%`; node.dataset.dragX = left; node.dataset.dragY = top; } renderMindConnections(); }; const end = () => { const item = state.mindNodes.find(nodeItem => nodeItem.id === node.querySelector('[data-delete-node]')?.dataset.deleteNode); if (item) { if (node.dataset.dragX) { item.x = Number(node.dataset.dragX); item.y = Number(node.dataset.dragY); } if (node.dataset.dragWidth) { item.width = Number(node.dataset.dragWidth); item.height = Number(node.dataset.dragHeight); } saveState(); } node.classList.remove('dragging'); document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', end); document.removeEventListener('pointercancel', end); renderMindConnections(); }; document.addEventListener('pointermove', move, { passive: false }); document.addEventListener('pointerup', end, { once: true }); document.addEventListener('pointercancel', end, { once: true }); }, true); }
document.addEventListener('DOMContentLoaded', enableDocumentMindDragging);
document.addEventListener('DOMContentLoaded', () => { const settings = document.getElementById('mindSettings'); const map = document.getElementById('mindMap'); if (!settings || !map || document.getElementById('mindInteractionMode')) return; settings.insertAdjacentHTML('beforeend', '<button class="mind-mode-button active" id="mindInteractionMode" type="button" aria-pressed="false" title="Alternar entre mover e redimensionar ideias">↔ Mover</button>'); const button = document.getElementById('mindInteractionMode'); map.classList.add('move-mode'); button.addEventListener('click', () => { const resizing = !map.classList.contains('resize-mode'); map.classList.toggle('resize-mode', resizing); map.classList.toggle('move-mode', !resizing); button.classList.toggle('active', true); button.textContent = resizing ? '⌗ Redimensionar' : '↔ Mover'; button.setAttribute('aria-pressed', String(resizing)); button.setAttribute('title', resizing ? 'Alternar para mover ideias' : 'Alternar para redimensionar ideias'); showToast(resizing ? 'Modo redimensionar ativo.' : 'Modo mover ativo.'); }); });

